# A tiny REST API: resources have URLs, HTTP methods say what to do, JSON carries the data.
import json

todos = {1: {"id": 1, "title": "Learn DNS", "done": True}}
next_id = 2


def handle(method, path, body=None):
    global next_id
    parts = path.strip("/").split("/")                 # "/todos/1" -> ["todos", "1"]
    if parts[0] != "todos":
        return 404, {"error": "no such resource"}
    if len(parts) == 1:                                 # the collection: /todos
        if method == "GET":
            return 200, list(todos.values())
        if method == "POST":
            data = json.loads(body)
            if "title" not in data:
                return 400, {"error": "title is required"}
            todo = {"id": next_id, "title": data["title"], "done": False}
            todos[next_id] = todo
            next_id += 1
            return 201, todo
        return 405, {"error": f"{method} not allowed here"}
    todo_id = int(parts[1])                             # one item: /todos/<id>
    if todo_id not in todos:
        return 404, {"error": f"todo {todo_id} not found"}
    if method == "GET":
        return 200, todos[todo_id]
    if method == "PUT":
        todos[todo_id] = {"id": todo_id, **json.loads(body)}
        return 200, todos[todo_id]
    if method == "DELETE":
        del todos[todo_id]
        return 204, None
    return 405, {"error": f"{method} not allowed here"}


calls = [("POST", "/todos", '{"title": "Learn HTTP"}'),
         ("GET", "/todos", None),
         ("PUT", "/todos/2", '{"title": "Learn HTTP", "done": true}'),
         ("PUT", "/todos/2", '{"title": "Learn HTTP", "done": true}'),     # same again: same result
         ("DELETE", "/todos/1", None),
         ("GET", "/todos/1", None),
         ("POST", "/todos", '{"name": "oops"}'),
         ("PATCH", "/todos", None)]
for method, path, body in calls:
    status, data = handle(method, path, body)
    text = json.dumps(data) if data is not None else "(no body)"
    print(f"{method:6} {path:9} -> {status} {text}")

